WITH filtered AS (SELECT id, store_name, city, region, opened_date, sqft, CEIL(sqft) AS sqft_whole, DATEDIFF(CURRENT_DATE(), opened_date) AS days_since_opened_date FROM stores WHERE region = 'South') SELECT s.id, s.store_name, s.sqft, x.sale_date, x.units FROM filtered s JOIN LATERAL (SELECT c.sale_date, c.units FROM store_sales c WHERE c.store_id = s.id ORDER BY c.revenue DESC, c.id DESC LIMIT 1) x ON TRUE;
